// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;
    function setUp() public { c = new ReentrancyDAO(); }
    function testFuzz_property(uint256 creditAmount, address actor, uint256 extraDeposit) public {
        vm.assume(actor != address(0));
        vm.assume(creditAmount > 0);
        vm.assume(extraDeposit > 0);

        vm.deal(actor, creditAmount);
        vm.prank(actor);
        c.deposit{value: creditAmount}();

        uint balanceBefore = address(c).balance;
        vm.prank(actor);
        c.withdrawAll();
        uint balanceAfterWithdraw = address(c).balance;

        address someone = address(0x1234);
        vm.deal(someone, extraDeposit);
        vm.prank(someone);
        c.deposit{value: extraDeposit}();

        uint expectedBalance = balanceBefore - creditAmount + extraDeposit;

        assertTrue(address(c).balance == expectedBalance);
    }
}
